using Microsoft.EntityFrameworkCore.TestModels;
using pengdows.efcore.adonet;

namespace pengdows.efcore.adonet.Specification.Tests;

// The model's message, photo and review ids are part of composite keys yet generated by the database, as identity columns.
// Behaviour reference (not copied): https://github.com/dotnet/efcore/blob/v10.0.11/test/EFCore.SqlServer.FunctionalTests/MonsterFixupChangedChangingSqlServerTest.cs
public abstract partial class MonsterFixupAdoNetTest<THost>
{
    public partial class AdoNetFixture
    {
        protected override void OnModelCreating<TMessage, TProduct, TProductPhoto, TProductReview, TComputerDetail, TDimensions>(
            ModelBuilder builder)
        {
            base.OnModelCreating<TMessage, TProduct, TProductPhoto, TProductReview, TComputerDetail, TDimensions>(builder);

            builder.Entity<TMessage>().Property(e => e.MessageId).UseIdentityColumn();
            builder.Entity<TProductPhoto>().Property(e => e.PhotoId).UseIdentityColumn();
            builder.Entity<TProductReview>().Property(e => e.ReviewId).UseIdentityColumn();
        }
    }
}
